import numpy as np
from scipy.optimize import brentq
from model import geometry,mode

def roots(e):
 s,t=geometry(e); b=t*t;c=1-2*np.log(s*t);D=b+c+2
 def f_old(x):
  ql=np.sqrt(1-b*x/D);qt=np.sqrt(1-x)
  return np.linalg.det([[-(b+c)*ql,-b*qt*qt-c],[D*ql*ql-2,(b+c)*qt]])
 def f_new(x):
  ql=np.sqrt(1-b*x/D);qt=np.sqrt(1-x)
  # h L/T, use rows after dropping i
  hL=(c+2)*ql/D; hT=(c+2)/(D*qt)
  return np.linalg.det([[-b*(ql+hL),-b*(qt+hT)],[(c+2-b)-D*ql*hL,(c+2-b)-D*qt*hT]])
 for name,f in [('old',f_old),('new',f_new)]:
  xs=np.linspace(1e-8,1-1e-8,10001); yy=np.array([f(x) for x in xs]); roots=[]
  for i in range(len(xs)-1):
   if yy[i]*yy[i+1]<0: roots.append(brentq(f,xs[i],xs[i+1]))
  print(name,roots, 'm',[s*s-b+b*x for x in roots])
for p in [0,1e5,8e5]:
 print('p',p);roots({'stretch':1.1,'pressure':p})
